var e=1,t=`ch04-baimenlou`,n=`1.0.0`,r=`曹操不容易`,i=`第四章 · 建安三年 · 下邳白门楼`,a=`水淹下邳，飞将吕布被绑上白门楼，刘备在旁轻飘飘递了一句话——杀吕布、收吕布，还是顺手先把刘备办了？`,o=12,s={preset:`guandu-frost`,name:`白门寒霜 · 孤城`,themeDir:`guandu-frost`,bgFile:`bg.jpg`,bgOpacity:.42,bgmFile:`bgm.mp3`,bgmOrigFile:`bgm-orig.mp3`,bgmLabel:`白门 · 寒霜 8x`,moodRates:{calm:1,tense:.94,cold:.9,fire:.88}},c={narrator:{id:`narrator`,name:`巡营所见`,side:`center`,tone:`neutral`},cao:{id:`cao`,name:`曹操`,role:`司空`,side:`right`,tone:`neutral`},lubu:{id:`lubu`,name:`吕布`,role:`飞将 · 阶下囚`,side:`left`,tone:`fire`},liubei:{id:`liubei`,name:`刘备`,role:`左将军 · 客将`,side:`left`,tone:`warn`},chengong:{id:`chengong`,name:`陈宫`,role:`吕布谋士`,side:`left`,tone:`info`},guojia:{id:`guojia`,name:`郭嘉`,role:`军师祭酒`,side:`left`,tone:`info`},xunyou:{id:`xunyou`,name:`荀攸`,role:`军师`,side:`left`,tone:`ok`},zhangliao:{id:`zhangliao`,name:`张辽`,role:`降将`,side:`left`,tone:`neutral`}},l={spared_lubu:{type:`boolean`,initial:!1,description:`是否收降吕布`},killed_liubei:{type:`boolean`,initial:!1,description:`是否在白门楼先办刘备`}},u=[{id:`coin`,label:`人心`,initial:4,max:6,warnAt:1,collapseAt:0,collapseEndingId:`E_collapse_coin`,warnText:`徐州士民与诸将疑心大起。`,redlineDesc:`人心归零时，徐州旧部哗变，曹军陷入泥潭。`},{id:`grain`,label:`军粮`,initial:4,max:6,warnAt:1,collapseAt:0,collapseEndingId:`E_collapse_grain`,warnText:`围城日久，泗水漕运将断。`,redlineDesc:`军粮清零时，大军被迫狼狈撤围，反遭吕布掩杀。`},{id:`troops`,label:`兵力`,initial:4,max:6,warnAt:1,collapseAt:0,collapseEndingId:`E_collapse_troops`,warnText:`攻城与内耗折损过大，主力见底。`,redlineDesc:`兵力清零时，无力镇压徐州与河北两面夹击。`}],d=`E_collapse_troops`,f=[{id:`yuan_threat`,label:`袁绍南顾`,initial:1,max:6,warnAt:4,overflowEndingId:`E_overflow_yuan`,warnText:`河北袁绍正虎视许都空虚，下邳不可久拖。`}],p=`N00_intro`,m=[{id:`act0`,num:`序`,title:`冬围下邳`,startNode:`N00_intro`},{id:`act1`,num:`案壹`,title:`水淹还是密约`,startNode:`N01_flood`},{id:`act2`,num:`案贰`,title:`白门楼缚飞将`,startNode:`N02_lubu`},{id:`act3`,num:`案叁`,title:`座上客刘玄德`,startNode:`N03_liubei`}],h={baimen:{id:`baimen`,term:`白门楼`,plain:`下邳城南门城楼，建安三年冬吕布、陈宫、高顺在此被曹操处决。`,source:`《三国志·吕布传》`},dingyuan:{id:`dingyuan`,term:`丁建阳与董卓`,plain:`吕布曾先后投靠丁原（字建阳）与董卓，又亲手杀之，刘备以此言断了曹操收降吕布之念。`,source:`《三国志·吕布传》`}},g={sub_liubei:{id:`sub_liubei`,surface:`明公不见布之事丁建阳及董太师乎？`,decode:`我刘备才不想看你收了天下第一猛将吕布，赶紧借旧账挑唆你把他勒死！`,note:`吕布临死怒骂刘备「大耳儿最叵信」，正是看穿此意。`}},_={},v=[{title:`白门楼生死一念`,when:{var:`spared_lubu`,op:`==`,value:!0},canonNote:`史载曹操本已心动，因刘备一言而决意缢杀吕布。`,playerHit:`你顶住了刘备的挑拨，亲手打开了「飞将归魏」的平行世界线。`,playerMiss:`你顺着历史大流处决了吕布，也放走了身边真正的劲敌。`,source:`《三国志·吕布传》`}],y=JSON.parse(`{"N00_intro":{"id":"N00_intro","act":"序 · 冬围下邳","title":"冻雨中的坚城","kind":"scene","mood":"cold","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安三年冬 · 下邳城外","text":"围攻下邳已近三月，寒雨连绵，北军疲惫不堪。城头吕布仍仗着并州铁骑与高顺陷阵营死守，而北面袁绍的斥候已频频现身黄河渡口。"},{"speaker":"guojia","sourceTag":"史载","text":"昔项籍七十余战未尝败北，一朝失势而身死国亡，恃勇无谋故也。今吕布气衰力竭，可引沂、泗二水灌城，一举克之！"},{"speaker":"cao","sourceTag":"拟写","text":"水淹下邳固然痛快，可城中尚有陈宫、高顺、张辽与十万徐州百姓——先看看城内递出来的密账再定！"}],"next":"N01_flood"},"N01_flood":{"id":"N01_flood","act":"案壹 · 水淹还是密约","title":"决堤前夜的两封密信","kind":"scene","mood":"tense","lines":[{"speaker":"xunyou","sourceTag":"拟写","text":"司空，今夜城里同时递出两条门路：一是吕布部将侯成、宋宪愿做内应绑缚吕布；二是有人传话，陈宫已对吕布彻底寒心。"}],"interaction":{"type":"counter_case","title":"案壹 · 下邳破城方略","docTitle":"《沂泗水势与城内密探簿》","prompt":"核对城外水情与城内军心两处实情：","minExpose":2,"claims":[{"id":"bm_c1_water","surface":"水工报称：决沂泗二水灌城，只淹城垣不伤百姓与粮仓。","proof":"巡营实查：冬水入城必毁半城民宅与冬粮，徐州士民恐从此恨曹氏入骨。"},{"id":"bm_c1_gaoshun","surface":"降探报称：高顺陷阵营与陈宫愿随吕布死战到底，绝无谈判余地。","proof":"巡营实查：吕布疑忌高顺、不听陈宫献策已久，陈宫只求保全徐州老母与全城百姓。"}]},"choices":[{"id":"bm_c1_canon_flood","label":"依史实决沂泗二水淹城，逼侯成宋宪献城绑吕布","hint":"人心 -1 · 袁绍南顾 +1（史实顺势）","isBait":true,"stampKind":"approve","stampText":"决水","replyText":"兵贵神速！掘开沂泗二水灌进下邳，看吕布还能在城头撑几天！","effects":[{"kind":"resource","resource":"coin","delta":-1,"reason":"水淹下邳伤及徐州民生"},{"kind":"deadline","deadline":"yuan_threat","delta":1,"reason":"水攻善后耗去半月光阴"}],"next":"N02_lubu"},{"id":"bm_c1_whatif_chengong","label":"【架空】停掘河堤！亲笔手书密约陈宫，以保全全城百姓换其开城归顺","hint":"平行世界线 · 陈宫高顺不死 · 完取徐州","stampKind":"reject","stampText":"密约","replyText":"不淹城！替孤写一封亲笔信射进城去给陈公台——当年兖州旧账一笔勾销，只要不开杀戒，徐州百姓与高顺陷阵营孤全数保全！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"免去水淹之祸，徐州百姓感念司空仁德"}],"next":"N_WI_chengong_open"}]},"N_WI_chengong_open":{"id":"N_WI_chengong_open","act":"架空世界线 · 东门夜谈陈公台","title":"重逢旧友于城下","kind":"scene","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安三年冬 · 下邳东门","text":"河堤未掘，下邳城中十万百姓免于冬寒灭顶之灾。三更时分，陈宫长叹一声亲开东门，高顺按剑立于其侧，原本注定死局的白门楼，竟在未流一滴血时和平易帜。"},{"speaker":"chengong","sourceTag":"拟写","text":"曹孟德，你肯为了徐州百姓收手不决堤，倒让宫刮目相看。今日城已献出，吕布已缚——你打算如何安顿我与高顺这支陷阵营？"}],"choices":[{"id":"wi_chengong_advisor","label":"复拜陈宫为徐州刺史、厚养其老母，共治东方大后方","hint":"军粮 +1 · 陈宫重归曹营，徐州铁板一块","stampKind":"approve","stampText":"重用","replyText":"公台当年弃我，只因我不惜民命；今日我守约护城，徐州就交给你来替我守着！","effects":[{"kind":"resource","resource":"grain","delta":1,"reason":"徐州完好无损，粮仓尽入曹营"}],"next":"E_WI_chengong_return"},{"id":"wi_gaoshun_legion","label":"整建制收编高顺「陷阵营」与张辽并州骑，打造天下第一重步兵","hint":"兵力 +2 · 陷阵营与虎豹骑合璧","stampKind":"reject","stampText":"收编","replyText":"高顺清白有威严、所将七百余人号称陷阵营！不拆散、不降职，孤给你们双倍铁甲，随我北战袁绍！","effects":[{"kind":"resource","resource":"troops","delta":2,"reason":"高顺陷阵营与张辽并州骑完整归心"}],"next":"E_WI_gaoshun_army"}]},"E_WI_chengong_return":{"id":"E_WI_chengong_return","act":"架空结局 · 公台归心","title":"陈宫重归曹营，徐州稳如磐石","kind":"ending","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安四年 · 彭城官署","text":"历史上决裂至死的曹操与陈宫，竟在下邳寒夜一笑泯恩仇。陈宫坐镇徐州安抚士民、转运漕粮，日后官渡之战时，再也没有后院叛乱之忧，刘备更永远失去了借徐州起家的机会。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"陈宫归心，徐州完好入魏","subtitle":"不掘河堤换公台 · 东方后院彻底安稳","tone":"ok","verdict":"你放下了报复兖州叛乱的私怨，换回了陈宫的绝世治才与完好无损的徐州粮仓。","buildName":"大度收心明主","buildQuote":"水淹下来是一座废城，信递进去是一座金山加个陈公台。"}},"E_WI_gaoshun_army":{"id":"E_WI_gaoshun_army","act":"架空结局 · 陷阵营归魏","title":"高顺张辽合璧，横扫河北","kind":"ending","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年 · 官渡前线","text":"史上最硬的步兵「陷阵营」没有埋骨白门楼，而是与虎豹骑并肩站在了官渡旷野。当高顺七百重甲死士顶着箭雨一步步踏碎袁军土山时，袁绍终于明白大势已去。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"收编高顺陷阵营，重步轻骑天下无敌","subtitle":"张辽高顺齐归曹 · 打造梦幻王牌军","tone":"ok","verdict":"张辽已足够威震逍遥津，如今再加上「每战必克」的高顺陷阵营，曹军锋锐提前达到了顶点。","buildName":"王牌收藏家","buildQuote":"吕布可以不要，高顺和张辽我全都要。"}},"N02_lubu":{"id":"N02_lubu","act":"案贰 · 白门楼缚飞将","title":"天下第一猛将的乞降","kind":"scene","mood":"tense","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安三年冬 · 下邳{{gloss:baimen}}","text":"大水灌城月余，侯成、宋宪反水将吕布五花大绑推上白门楼。吕布大呼绳索太紧，你笑言「缚虎不得不急」。吕布仰头高声喊道：「明公所患不过于布，今已服矣！明公为大将，布为骑将，天下不足定也！」"},{"speaker":"liubei","sourceTag":"史载","text":"司空且慢！{{subtext:sub_liubei}}"},{"speaker":"lubu","sourceTag":"史载","text":"大耳儿最叵信！当年辕门射戟救你性命，今日反倒落井下石！"}],"choices":[{"id":"bm_c2_canon_kill","label":"听刘备之言，传令缢杀吕布、收降张辽","hint":"人心 +1 · 进入案叁处置刘备（史实顺势）","isBait":true,"stampKind":"approve","stampText":"缢杀","replyText":"玄德言之有理，缚虎容易养虎难！拉下去缢杀，枭首示众！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"斩除反复无常的飞将，诸将安心"}],"next":"N03_liubei"},{"id":"bm_c2_whatif_spare","label":"【架空】无视刘备挑拨！亲手替吕布松绑，封为先锋骑都尉","hint":"平行世界线 · 「明公步军，布为骑将」成真","stampKind":"dirty","stampText":"收布","replyText":"丁原董卓御下无方，关我曹孟德何事？松绑！封吕奉先为前部骑都尉，孤今天就让你去撕袁绍的阵！","effects":[{"kind":"var_set","var":"spared_lubu","value":true},{"kind":"resource","resource":"troops","delta":1,"reason":"天下第一飞将与赤兔马正式入列曹营"}],"next":"N_WI_lubu_general"}]},"N_WI_lubu_general":{"id":"N_WI_lubu_general","act":"架空世界线 · 养虎为患还是如虎添翼","title":"如何驾驭一头猛虎","kind":"scene","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安四年春 · 许都校场","text":"白门楼上你亲手给吕布松了绑，刘备脸色发白不敢多言。回到许都后，吕布一人一戟在校场连挑数将无人能敌，但郭嘉私下提醒你：猛虎既已入栏，链子怎么拴决定你的生死。"},{"speaker":"guojia","sourceTag":"推演","text":"司空，吕布有勇无谋、重利轻义。若质其家小在许都、只给精骑不给独镇地盘，由张辽监军北战袁绍，则天下无敌；若封其为徐州牧放归独镇，不出三年必生肘腋之变！"}],"choices":[{"id":"wi_lubu_leash","label":"留其家小于许都，只领五千虎豹骑为官渡总先锋、由张辽副之","hint":"军粮 -1 · 完美拴住飞将，正面踏平官渡","stampKind":"approve","stampText":"拴虎","replyText":"奉先只管骑赤兔马冲阵杀敌，粮草封赏孤管够，许都豪宅替你养着妻女！","effects":[{"kind":"resource","resource":"grain","delta":-1,"reason":"重金厚禄供养吕布并州骑兵"}],"next":"E_WI_lubu_conquer"},{"id":"wi_lubu_governor","label":"示以推心置腹，放吕布回镇淮南牵制袁术与孙策","hint":"人心 +1 · 赌一把飞将忠心","stampKind":"dirty","stampText":"放虎","replyText":"疑人不用、用人不疑！把淮南交给奉先，替孤把江东小霸王挡在长江南边！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"展现惊人胸襟，天下豪杰侧目"}],"next":"E_WI_lubu_betray"}]},"E_WI_lubu_conquer":{"id":"E_WI_lubu_conquer","act":"架空结局 · 飞将破河北","title":"明公步军，布为骑将，横扫官渡","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年 · 白马坡前","text":"白马坡上，根本没轮到关羽出场——吕布挺画戟策赤兔直冲颜良中军，三合挑落河北上将，连文丑亦在乱军中被吕布张辽联手击溃！曹操坐镇中军大笑：「早知奉先如此好用，当年何必废话！」"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"明公步军布骑将，横扫袁绍定北方","subtitle":"拴住猛虎的正确用法 · 三国最强组合","tone":"ok","verdict":"吕布不是不能用，而是只能当尖刀、绝不能当诸侯。你用许都质子与张辽副将稳稳拴住了这头猛虎，换来一场毫无悬念的北方横扫。","buildName":"驯虎大师曹操","buildQuote":"玄德当年劝我杀他，幸好我没听。"}},"E_WI_lubu_betray":{"id":"E_WI_lubu_betray","act":"架空结局 · 飞将再反","title":"三年后淮南惊变，猛虎终究咬主","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年秋 · 官渡后方急报","text":"正当你与袁绍在官渡僵持不下时，八百里急报传来：吕布果然没忍住袁绍封王的诱惑，在淮南再次反叛直扑许都！你在官渡大帐扶额苦笑——刘备那句「丁建阳与董太师」，终究还是应验了。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"三年后飞将反噬，许都惊变","subtitle":"放虎归山终成大患 · 历史冷笑","tone":"warn","verdict":"你赌上了信任，吕布却兑现了他一贯的职业履历。这便是放猛虎独镇一方的昂贵代价。","buildName":"悲情信虎人","buildQuote":"早知道该留他家小在许都的……"}},"N03_liubei":{"id":"N03_liubei","act":"案叁 · 座上客刘玄德","title":"除掉猛虎，身边还有真龙","kind":"scene","mood":"cold","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安三年冬 · 白门楼宴席","text":"吕布与陈宫已被处决，徐州平定。庆功席上，刘备举杯恭贺，态度谦卑得挑不出一丝毛病；帐外关羽、张飞按刀肃立。程昱与郭嘉却同时递来密札：刘备有雄才而甚得众心，终不为人下，不如早图之！"},{"speaker":"guojia","sourceTag":"史载","text":"司空，今收天下英雄，若杀刘备恐失豪杰之心；不如软禁许都、以厚禄养之，绝不放其领兵出外。"},{"speaker":"liubei","sourceTag":"拟写","text":"备乃败军之将，蒙司空收留已是天恩，唯愿随司空回许都效犬马之劳。"}],"choices":[{"id":"bm_c3_canon_keep","label":"依史实礼遇刘备带回许都，日后青梅煮酒再论英雄","hint":"人心 +1 · 史实收束（留下毕生劲敌）","isBait":true,"stampKind":"approve","stampText":"礼遇","replyText":"方今收英雄时也，杀一人而失天下之心，不可！玄德请随孤同返许都！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"礼遇刘备赢得天下士林美誉"}],"next":"E_canon_baimen"},{"id":"bm_c3_whatif_kill_liu","label":"【架空】趁酒席摔杯为号！在白门楼先办掉刘备，顺势招降关羽张飞","hint":"平行世界线 · 一劳永逸还是激怒关张？","stampKind":"dirty","stampText":"摔杯","replyText":"吕布只是匹夫，刘备才是心腹大患！今日连这大耳儿一并解决，省得日后煮酒论什么英雄！","effects":[{"kind":"var_set","var":"killed_liubei","value":true},{"kind":"resource","resource":"coin","delta":-1,"reason":"宴席骤发难，士林一时哗然"}],"next":"N_WI_kill_liubei"}]},"N_WI_kill_liubei":{"id":"N_WI_kill_liubei","act":"架空世界线 · 白门楼摔杯","title":"斩断季汉的起点","kind":"scene","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安三年冬 · 下邳行辕","text":"酒杯摔碎的瞬间，帐内伏兵齐出将刘备按倒在地！帐外关羽、张飞闻变提刀怒吼，正要拼死杀进帅府。此时局势一触即发——你必须在一息之间决定怎么收场！"},{"speaker":"zhangliao","sourceTag":"拟写","text":"司空！关羽、张飞皆万人敌，硬拼必伤我中军精锐！是立刻斩刘备示众全军围杀关张，还是只软禁刘备作人质、逼关张卸甲效命？"}],"choices":[{"id":"wi_exec_liu","label":"当场宣诏以「密通袁术」之罪斩刘备，调重弩齐射困死关张","hint":"兵力 -1 · 彻底抹除蜀汉世界线","stampKind":"dirty","stampText":"立斩","replyText":"留他一天就多一天后患！宣天子诏立斩刘备，乱箭围杀，绝不放虎归山！","effects":[{"kind":"resource","resource":"troops","delta":-1,"reason":"强行围杀暴怒的关张折损中军精锐"}],"next":"E_WI_no_shu"},{"id":"wi_hostage_liu","label":"不杀刘备，将其明升暗降软禁许都高塔，遣关张分领偏师北战袁绍","hint":"人心 +1 · 既得关张之勇，又不背杀贤骂名","stampKind":"approve","stampText":"软禁","replyText":"告诉关羽张飞：你们大哥在许都锦衣玉食，只要你们替孤砍下颜良文丑的脑袋，孤保他富贵一生！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"免背杀贤恶名，又将刘备牢牢锁在掌心"}],"next":"E_WI_cage_dragon"}]},"E_WI_no_shu":{"id":"E_WI_no_shu","act":"架空结局 · 天下无蜀","title":"白门楼斩玄德，三国再无季汉","kind":"ending","mood":"cold","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安十三年 · 荆州无主","text":"刘备与关张的传奇在建安三年冬戛然而止。虽背上了几年的骂名，但此后十年再无人能联合江东抗曹，隆中对永远成了一纸空谈，诸葛亮亦终老南阳茅庐。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"白门楼斩玄德，天下再无季汉","subtitle":"斩草除根 · 历史上最冷酷的捷径","tone":"ok","verdict":"你宁可背负一时骂名，也要在真龙未起飞前折断他的翅膀。这很残酷，却也是最快通往一统的冷血路线。","buildName":"冷酷断根霸主","buildQuote":"天下英雄唯使君与操耳——现在只剩孤一个了。"}},"E_WI_cage_dragon":{"id":"E_WI_cage_dragon","act":"架空结局 · 金笼锁龙","title":"许都高塔养玄德，关张为魏斩颜良","kind":"ending","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年 · 许都园圃","text":"你听进了郭嘉的后半句话——不杀，但也绝不放！刘备在许都种了一辈子菜，再也没机会借截击袁术逃出徐州；而关羽与张飞为了保住大哥体面，硬生生替你打穿了河北半壁江山。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"金笼锁玄德，关张替魏平河北","subtitle":"不杀不放 · 最高明的帝王权术","tone":"ok","verdict":"既保留了礼贤下士的好名声，又彻底封死了刘备东山再起的可能，堪称白门楼最优解。","buildName":"帝王锁龙手","buildQuote":"种菜就好好在许都种一辈子，打仗的事交给云长和翼德就行。"}},"E_canon_baimen":{"id":"E_canon_baimen","act":"史实结局 · 白门楼落幕","title":"缢杀吕布，带走真正的对手","kind":"ending","mood":"cold","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安三年腊月 · 许都官道","text":"飞将吕布与谋士陈宫的头颅悬在了许都城门，你收服了张辽，又把笑容谦逊的刘备带回了身边。一切都照着正史演了下去——只是你还没想到，半年后这人就会夺走你的徐州，纠缠你整整二十年。"}],"ending":{"badge":"史实收束 · CANON","title":"白门楼除吕布，留刘备于身侧","subtitle":"重演历史 · 英雄惜英雄的代价","tone":"warn","verdict":"你走完了经典的白门楼正史。不妨跳回案壹、案贰或案叁，试试不淹城收陈宫高顺、真收吕布，或者直接把刘备锁死在许都！","buildName":"白门楼正史见证者","buildQuote":"杀了头猛虎，却亲手牵回了一条潜龙。"}},"E_collapse_coin":{"id":"E_collapse_coin","act":"红线崩盘","title":"徐州失心，遍地烽烟","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"text":"人心归零，徐州士民群起抗曹，下邳战局彻底失控。"}],"ending":{"badge":"红线崩盘 · 人心归零","title":"徐州民变，攻城大败","subtitle":"人心触及红线","tone":"danger","isCollapse":true,"verdict":"失尽徐州民心，连城外大营都站不住脚。","buildName":"失道寡助者","buildQuote":"城还没破，人心先散了。"}},"E_collapse_grain":{"id":"E_collapse_grain","act":"红线崩盘","title":"围城断粮，狼狈撤军","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"text":"泗水粮道断绝，围城大军无以为继，被吕布反冲出城大破。"}],"ending":{"badge":"红线崩盘 · 军粮归零","title":"久围断炊，反遭吕布掩杀","subtitle":"军粮触及红线","tone":"danger","isCollapse":true,"verdict":"攻城最怕旷日持久把自家吃垮。","buildName":"断粮围城者","buildQuote":"没饿死城里的吕布，先饿垮了城外的自己。"}},"E_collapse_troops":{"id":"E_collapse_troops","act":"红线崩盘","title":"兵力耗尽，徐州折戟","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"text":"精锐耗尽，曹军被迫放弃徐州狼狈退回兖州。"}],"ending":{"badge":"红线崩盘 · 兵力归零","title":"精锐折尽，败走下邳","subtitle":"兵力触及红线","tone":"danger","isCollapse":true,"verdict":"血战无度，连守住营盘的兵力都没剩下。","buildName":"竭泽而渔者","buildQuote":"打下邳把自己打空了，便宜了河北袁绍。"}},"E_overflow_yuan":{"id":"E_overflow_yuan","act":"死线溢出","title":"袁绍乘虚南下，许都告急","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"text":"下邳久攻不下，袁绍趁虚渡过黄河直扑许都，你不得不仓皇撤围回救。"}],"ending":{"badge":"死线溢出 · 袁绍南顾","title":"后院许都告急，功亏一篑","subtitle":"袁绍南顾达到满格","tone":"danger","isDeadlineOverflow":true,"verdict":"在下邳拖得太久，让河北巨兽抓住了空门。","buildName":"顾此失彼者","buildQuote":"眼里只盯着吕布，忘了背后的袁本初。"}}}`),b={schemaVersion:1,id:t,version:n,title:r,subtitle:i,tagline:a,estimatedMinutes:12,theme:s,cast:c,varsSchema:l,resources:u,multiCollapseEndingId:d,deadlines:f,startNode:p,acts:m,gloss:h,subtexts:g,refs:_,historyDossier:v,nodes:y};export{m as acts,c as cast,f as deadlines,b as default,o as estimatedMinutes,h as gloss,v as historyDossier,t as id,d as multiCollapseEndingId,y as nodes,_ as refs,u as resources,e as schemaVersion,p as startNode,g as subtexts,i as subtitle,a as tagline,s as theme,r as title,l as varsSchema,n as version};